contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint value) public payable {
        require(address(this).balance >= amount);
        require(address(this).balance >= value);

        // make sure the caller is not the owner
        require(msg.sender != c.owner());

        // record pre-call observable state
        uint balBefore = address(c).balance;
        uint depBefore = c.depositsCount();

        // trigger fallback to increment depositsCount
        c.fallback{value: amount}();

        uint balAfterFallback = address(c).balance;
        uint depAfterFallback = c.depositsCount();

        // owner-only functions must revert for non-owner
        bool revWithdrawAll;
        try c.withdrawAll() { revWithdrawAll = false; } catch { revWithdrawAll = true; }

        bool revWithdraw;
        try c.withdraw(value) { revWithdraw = false; } catch { revWithdraw = true; }

        bool revSendMoney;
        try c.sendMoney(address(this), value) { revSendMoney = false; } catch { revSendMoney = true; }

        assert(revWithdrawAll && revWithdraw && revSendMoney && balAfterFallback == balBefore + amount && depAfterFallback == depBefore + 1);
    }

    receive() external payable {}

    fallback() external payable {}
}

