contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 wVal, bool useWithdrawAll) public payable {
        require(address(this).balance >= wVal, "insufficient test balance");

        // Fund C so there is something to withdraw.
        (bool sent, ) = address(c).call{value: wVal}("");
        require(sent, "funding failed");

        uint256 balBefore = address(c).balance;

        bool reverted;
        if (useWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint256 balAfter = address(c).balance;
            assert(reverted ? balAfter == balBefore : balAfter == 0);
        } else {
            require(wVal <= balBefore, "withdraw amount exceeds balance");
            try c.withdraw(wVal) {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint256 balAfter = address(c).balance;
            assert(reverted ? balAfter == balBefore : balAfter == balBefore - wVal);
        }
    }

    receive() external payable {}
}

