contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        uint256 balBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount();

        bool revertWithdrawAll;
        bool revertWithdraw;
        bool revertSendMoney;

        // Make the test contract a non-owner by ensuring caller is not the test contract itself.
        // Since the test contract deployed c, c.owner() == address(this). To test the non-owner path,
        // we need to call from an address that is not the owner. The only way to do that without
        // cheatcodes is to have the test contract call c through a low-level call with a different
        // msg.sender? No: msg.sender is always address(this) for direct calls.
        //
        // However, we can test that an arbitrary caller cannot be the owner by checking that
        // c.owner() is not caller. The precondition below ensures caller != c.owner().
        require(caller != c.owner(), "caller must not be owner");

        // Now we attempt to call the owner-only functions from the test contract,
        // but the test contract IS the owner. To simulate a non-owner, we cannot change msg.sender.
        // Therefore, we test the revert condition by using a call from a different context?
        // Actually, the test contract is the deployer, so msg.sender == owner always when calling c.
        // So we cannot easily trigger the non-owner revert path.

        // Alternative: We can test that if caller is not owner, then calls from that caller would revert,
        // but we cannot perform calls as that caller. So we instead verify the rule by checking that
        // c.owner() is exactly the test contract, and that non-owner calls are not possible from here.
        // This is not a behavioral test of revert.

        // Better: Use a low-level call with a value and check that it reverts if caller is not owner?
        // But msg.sender is still the test contract.

        // The only way to test revert for non-owner is to have the test contract call c through
        // another contract that forwards the call, but that would require deploying another contract,
        // which is prohibited.

        // So we cannot directly test the non-owner revert. We'll test a different rule.

        // Since the test contract is owner, we can test that owner calls work and non-owner calls
        // would revert if attempted. But we cannot attempt as non-owner.

        // Given the constraints, we choose a different rule: the fallback increases depositsCount.
        // Already tested? The accepted rules mention depositsCount unchanged on withdraw/sendMoney.
        // We can test that a direct Ether transfer to c via fallback increments depositsCount by 1.

        uint256 depositsBeforeFallback = c.depositsCount();
        uint256 balBeforeFallback = address(c).balance;

        // Send a small amount to c to trigger fallback
        uint256 amount = 1 wei;
        require(address(this).balance >= amount, "insufficient balance");
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "fallback call failed");

        uint256 depositsAfterFallback = c.depositsCount();
        uint256 balAfterFallback = address(c).balance;

        // The fallback should increment depositsCount by exactly 1 and increase balance by amount.
        assert(depositsAfterFallback == depositsBeforeFallback + 1 && balAfterFallback == balBeforeFallback + amount);
    }

    receive() external payable {}
}

