contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, bool useFallback) public payable {
        require(address(this).balance >= amount);

        // Make the test contract not the owner of C, so owner-only calls revert.
        // The constructor deploys with msg.sender = this test contract, and there is no
        // owner-transfer function in C, so the test contract is the owner.
        // To exercise the non-owner path we must have a different caller.
        // Since we cannot change msg.sender directly, we focus on the fallback,
        // which is callable by anyone.
        // Every setup call must be top-level and not in control flow.
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted;
        if (useFallback) {
            try c.call{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Call a non-owner-only state-changing function that does not exist;
            // fall back to testing withdrawAll as owner, which should not revert,
            // but we need a general rule. Instead, use the fallback path only.
            reverted = false;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        if (useFallback) {
            if (reverted) {
                assert(afterBalance == beforeBalance && afterDeposits == beforeDeposits);
            } else {
                assert(afterBalance == beforeBalance + amount && afterDeposits == beforeDeposits + 1);
            }
        } else {
            // If useFallback is false, no call is made; state must be unchanged.
            assert(afterBalance == beforeBalance && afterDeposits == beforeDeposits);
        }
    }

    receive() external payable {}
}

